import{_ as o,o as e,c as t,ag as r}from"./chunks/framework.4s5LDCII.js";const h=JSON.parse('{"title":"建议驿站（SageRelay）","description":"","frontmatter":{},"headers":[],"relativePath":"project/CONTEXT.md","filePath":"project/CONTEXT.md"}'),n={name:"project/CONTEXT.md"};function s(p,a,g,i,l,d){return e(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="建议驿站-sagerelay" tabindex="-1">建议驿站（SageRelay） <a class="header-anchor" href="#建议驿站-sagerelay" aria-label="Permalink to &quot;建议驿站（SageRelay）&quot;">​</a></h1><p>第三方建设的健康与产品安全科普知识库：内容全部溯源自国家权威部门及官方指定机构发布的文件，项目本身不自称官方，页面显著声明&quot;非官方、一切以原文为准&quot;。目标用户为 25–60 岁的家庭决策者，典型场景：为慢病家人查官方饮食指导，为安全敏感的消费查国标要求。</p><blockquote><p>名字出处：驿站是中国古代官方文书接力传递的节点——本站收录权威指南、附上出处、一站站递送给需要的人。SageRelay：Sage（权威）+ Relay（接力）。命名沿革见 ADR 0008、0009（曾用名「一枝春」）。</p></blockquote><h2 id="language" tabindex="-1">Language <a class="header-anchor" href="#language" aria-label="Permalink to &quot;Language&quot;">​</a></h2><h3 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h3><p><strong>本库</strong>: 本项目自称&quot;建议驿站&quot;。第三方权威来源汇编知识库，永不自称&quot;官方&quot;。 <em>Avoid</em>: 官方科普、官方平台、权威发布、一枝春（旧名）</p><p><strong>词条</strong>: 知识库的最小单元：速览卡 + 行动清单 + 常见误区（如有） + 原文引用与溯源信息（发布机构、发布日期、原文链接、版本状态）。 <em>Avoid</em>: 文章、帖子、百科条目、发文字号（原文页自带，不在本站转述）</p><p><strong>导读</strong>: 词条开头说明&quot;这份文件适用于谁&quot;的短文，不新增任何医学论断。</p><p><strong>速览卡</strong>: 词条顶部的一屏摘要：关键数字与一句话结论，全部取自原文，给只需要答案的人。</p><p><strong>行动清单</strong>: 按&quot;买 → 做 → 吃 → 动 → 测/就医&quot;场景组织的可执行步骤。每条逐条溯源原文，&quot;出处&quot;为直达原文 PDF 对应页的链接（#page=N）；语言可口语化，数字与结论不得改动。 <em>Avoid</em>: 建议（无出处的）、攻略、章节号纯文字（用户核验不到）</p><p><strong>本站提示</strong>: 行动清单中显式标注的中性工具性提示（如使用限盐勺、查看配料表钠含量的方法），永不涉及医学判断，与原文内容严格区分。 <em>Avoid</em>: 小贴士（易与原文内容混淆）</p><h3 id="来源" tabindex="-1">来源 <a class="header-anchor" href="#来源" aria-label="Permalink to &quot;来源&quot;">​</a></h3><p><strong>一级来源</strong>: 国务院部委及直属机构发布的文件（卫健委、疾控局、标准委、市场监管总局等）。</p><p><strong>二级来源</strong>: 官方指定专业机构发布的文件（中国营养学会、中国疾控中心、中国消费者协会），展示时必须标注来源级别。</p><p><strong>三级来源</strong>: 权威医疗机构（三甲医院等）官方科普与经资质认证的医生科普。须资质可核、标注作者，只链接摘要不整篇转载；与一级来源冲突时以一级为准。后置启用。</p><p><strong>白名单</strong>: 允许收录的机构总清单（一级 + 二级 + 三级），清单外一律不收。 <em>Avoid</em>: 权威媒体（商业媒体不在白名单内）</p><h3 id="内容域" tabindex="-1">内容域 <a class="header-anchor" href="#内容域" aria-label="Permalink to &quot;内容域&quot;">​</a></h3><p><strong>食养指南域</strong>: 国家卫健委印发的慢性病食养指南系列与《中国居民膳食指南》。首期唯一内容域。</p><p><strong>国标科普域</strong>: 解读消费品所执行的强制性/推荐性国家标准。第二期内容域。</p><p><strong>资质核查域</strong>: 仅提供官方违规 APP 黑名单查询与选型判断标准，不推荐任何具体软件。 <em>Avoid</em>: 软件推荐、工具推荐</p><p><strong>分地区食谱</strong>: 食养指南自带的按地区/季节划分的食谱示例，是&quot;地域&quot;维度的唯一权威形式。 <em>Avoid</em>: 各地常见病（独立域已砍除）</p><h3 id="二期概念" tabindex="-1">二期概念 <a class="header-anchor" href="#二期概念" aria-label="Permalink to &quot;二期概念&quot;">​</a></h3><p><strong>文献检索助手</strong>（规划中）: 二期引入的 AI 层，只返回原文出处与原句，不生成任何医学结论。 <em>Avoid</em>: 健康顾问、AI 医生、智能问答</p><h3 id="版本" tabindex="-1">版本 <a class="header-anchor" href="#版本" aria-label="Permalink to &quot;版本&quot;">​</a></h3><p><strong>现行 / 已废止</strong>: 词条的版本状态。新版发布后旧版归档并标注&quot;已被 XX 年版替代&quot;，永不删除。</p><h3 id="红线" tabindex="-1">红线 <a class="header-anchor" href="#红线" aria-label="Permalink to &quot;红线&quot;">​</a></h3><p><strong>逐条溯源</strong>: 行动清单中的每条建议必须能在官方原文中找到对应原句或数字；找不到就不写。本站提示除外，但必须显式标注。</p><p><strong>不背书</strong>: 永不推荐具体商业品牌、商品、药品、保健食品；推荐对象只有权威文件与判断标准。 <em>Avoid</em>: 带货、软文、好物推荐</p>',28)])])}const m=o(n,[["render",s]]);export{h as __pageData,m as default};
